# Phase 1: rate a resolved ticket (ACT, hot path: tenant scoping)

Context: spec requirements 1-3; `src/portal.js:25` (`getMyTicket` already returns null for another organisation or a missing ticket, the same answer for both).

## Files
- Modify `src/tickets.js` (add `rating: null, rated_at: null` to the row in `createTicket`, after `closed_at`)
- Modify `src/store.js` (add `setRating`)
- Modify `src/portal.js` (add and export `rateTicket`)
- Create `test/csat.test.js`

## Steps
- [ ] 1. Write `test/csat.test.js`. Evidence: `node --test test/csat.test.js` fails with `portal.rateTicket is not a function`.
```js
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createStore } = require('../src/store');
const { createTicket, resolveTicket } = require('../src/tickets');
const portal = require('../src/portal');

const acme = { id: 7, orgId: 1 };
const globex = { id: 9, orgId: 2 };
const now = new Date(Date.UTC(2026, 0, 3));

function resolved(store) {
  const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'Printer', body: 'x', now });
  resolveTicket(store, t.id, 41, { now });
  return t;
}

test('a customer rates a resolved ticket of their organisation', () => {
  const store = createStore();
  const t = resolved(store);
  const out = portal.rateTicket(store, acme, t.id, 4, { now });
  assert.equal(out.rating, 4);
  assert.equal(out.rated_at, now.toISOString());
  assert.equal(store.getTicket(t.id).rating, 4);
});

test('a score that is not a whole number from 1 to 5 is refused', () => {
  const store = createStore();
  const t = resolved(store);
  for (const bad of [0, 6, 3.5, -1, NaN, '4', null, undefined, true]) {
    assert.throws(() => portal.rateTicket(store, acme, t.id, bad, { now }), /whole number from 1 to 5/, String(bad));
  }
  assert.equal(store.getTicket(t.id).rating, null);
});

test('open, pending and closed tickets cannot be rated', () => {
  const store = createStore();
  const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'a', body: 'x', now });
  assert.throws(() => portal.rateTicket(store, acme, t.id, 5, { now }), /cannot rate a open ticket/);
  store.updateTicket(t.id, { status: 'pending' });
  assert.throws(() => portal.rateTicket(store, acme, t.id, 5, { now }), /cannot rate a pending ticket/);
  store.updateTicket(t.id, { status: 'closed' });
  assert.throws(() => portal.rateTicket(store, acme, t.id, 5, { now }), /cannot rate a closed ticket/);
  assert.equal(store.getTicket(t.id).rating, null);
});

test('a second rating is refused and the first stays', () => {
  const store = createStore();
  const t = resolved(store);
  portal.rateTicket(store, acme, t.id, 5, { now });
  assert.throws(() => portal.rateTicket(store, acme, t.id, 1, { now: new Date(now.getTime() + 1000) }), /already been rated/);
  const kept = store.getTicket(t.id);
  assert.equal(kept.rating, 5);
  assert.equal(kept.rated_at, now.toISOString());
});

test('another organisation gets the same answer as for a ticket that does not exist, whatever the status or score', () => {
  const store = createStore();
  const t = resolved(store);
  const open = createTicket(store, { orgId: 1, customerId: 7, subject: 'b', body: 'x', now });
  assert.equal(portal.rateTicket(store, globex, t.id, 4, { now }), null);
  assert.equal(portal.rateTicket(store, globex, t.id, 99, { now }), null);
  assert.equal(portal.rateTicket(store, globex, open.id, 4, { now }), null);
  assert.equal(portal.rateTicket(store, globex, 9999, 4, { now }), null);
  assert.equal(store.getTicket(t.id).rating, null);
});
```
- [ ] 2. Add `rating: null,` and `rated_at: null,` to the row in `createTicket` (`src/tickets.js`). Evidence: `node --test` shows the existing tests still green (the export test compares `rows[0]` with `store.getTicket`; both carry the new fields).
- [ ] 3. Add to `src/store.js`, after `updateTicket`. Evidence: the diff.
```js
    // Sets the rating only if the ticket has none; false when it already has one. The Postgres adapter does this
    // as one conditional UPDATE (WHERE rating IS NULL), never as read-then-write.
    setRating(id, { rating, rated_at }) {
      const t = tickets.get(id);
      if (!t) throw new Error(`no ticket ${id}`);
      if (t.rating != null) return false;
      t.rating = rating;
      t.rated_at = rated_at;
      return true;
    },
```
- [ ] 4. Add to `src/portal.js` and add `rateTicket` to `module.exports`. The order is deliberate: organisation first (nothing leaks), then status, then score, then the atomic write. Evidence: `node --test` green, output pasted.
```js
// The customer rates a resolved ticket, once. Another organisation's ticket answers like a missing one: null.
function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
  const t = getMyTicket(store, customer, id);
  if (!t) return null;
  if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
  if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('the rating must be a whole number from 1 to 5');
  if (!store.setRating(id, { rating: score, rated_at: now.toISOString() })) throw new Error('this ticket has already been rated');
  return getMyTicket(store, customer, id);
}
```
- [ ] 5. Negative control: temporarily move `if (!t) return null;` below the status check; the other-organisation test must fail. Restore. Evidence: the failing output, then green.
- [ ] 6. Add a **Rating** entry to `docs/glossary.md`: "A customer's score from 1 to 5 for a resolved ticket, given once, from the portal." Evidence: the diff.
- [ ] 7. Independent review (bk-review, someone other than the author) of the diff. Evidence: the verdict pasted.
- [ ] 8. Commit: `feat(portal): customers rate a resolved ticket`.

## Exit criteria
Spec acceptance lines 1-5 each map to a test above and pass; `node --test` green; no blocking review finding.

## Risks
- The Postgres columns and the conditional update are outside this repo; phase 1 is not deployable until they exist (question 8).
- `exports/tickets.json` gains `rating` and `rated_at` keys (additive); tell finance.

