'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { createStore } = require('../src/store');
const { createTicket, assignTicket, resolveTicket } = require('../src/tickets');
const portal = require('../src/portal');
const { csatWeekly } = require('../src/jobs/csat-weekly');

const DAY = 24 * 60 * 60 * 1000;
const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
const acme = { id: 7, orgId: 1 };

function rated(store, agent, score, when) {
  const t = createTicket(store, { orgId: 1, customerId: 7, subject: 's', body: 'x', now: at(0) });
  if (agent) assignTicket(store, t.id, agent);
  resolveTicket(store, t.id, agent || 1, { now: at(0) });
