test('ratings 5, 4 and 1 in seven days give three ratings and 3.33; an eight-day-old rating is not counted', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'helpdesk-csat-'));
  try {
    const store = createStore();
    rated(store, 41, 5, at(9));
    rated(store, 41, 4, at(10));
    rated(store, 41, 1, at(12));
    rated(store, 41, 2, at(4));
    rated(store, 42, 3, at(7));
    rated(store, null, 1, at(11));
