- [ ] 4. Create `src/jobs/csat-weekly.js`. Evidence: `node --test` green, output pasted.
```js
'use strict';
// Nightly. Writes exports/csat-weekly.json: for each agent, how many ratings their tickets received in the past
// seven days and the average score. Agents with no ratings in the window are left out.
const fs = require('node:fs');
const path = require('node:path');
const { EXPORT_DIR } = require('./export-tickets');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function csatWeekly(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
  const since = now.getTime() - WINDOW_DAYS * DAY;
  const byAgent = new Map();
  for (const t of store.listTickets()) {
    if (t.rating == null || !t.assignee_id) continue;
    const ratedAt = new Date(t.rated_at).getTime();
    if (ratedAt < since || ratedAt > now.getTime()) continue;
    const s = byAgent.get(t.assignee_id) || { agent_id: t.assignee_id, ratings: 0, total: 0 };
    s.ratings += 1;
    s.total += t.rating;
    byAgent.set(t.assignee_id, s);
  }
  const agents = [...byAgent.values()]
    .map(({ agent_id, ratings, total }) => ({ agent_id, ratings, average: Math.round((total / ratings) * 100) / 100 }))
    .sort((a, b) => a.agent_id - b.agent_id);
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'csat-weekly.json');
  fs.writeFileSync(file, JSON.stringify({ generated_at: now.toISOString(), window_days: WINDOW_DAYS, agents }, null, 2) + '\n');
  return { file, agents };
}

module.exports = { csatWeekly, WINDOW_DAYS };
```
